export interface ShiftTracker { mark(): void; shift(point: Vec): { dx: number; dy: number } }
export function trackScreenShift(camera: Camera, canvas: HTMLCanvasElement): ShiftTracker {
  type Snapshot = {
    view: Float32Array;
    viewProjection: Float32Array;
    viewport: { x: number; y: number; width: number; height: number };
    backingWidth: number;
    backingHeight: number;
    cssWidth: number;
    cssHeight: number;
  };
  const copyMat = (m: any): Float32Array => new Float32Array(m);
  const snapshot = (): Snapshot => {
    const cssWidth = canvas.clientWidth || canvas.width;
    const cssHeight = canvas.clientHeight || canvas.height;
    const aspect = getEffectiveAspectRatio(camera, cssWidth, cssHeight);
    const view = getViewMatrix(camera);
    const viewProjection = getViewProjectionMatrix(camera, aspect);
    const viewport = resolveCameraViewport(camera, cssWidth, cssHeight);
